+namespace {
+
+// Speed at which a coin sinks once it is in water (pixels per second).
+const float WATER_SINK_SPEED = 100.0f;
+// Gravity multiplier while in water.
+const float WATER_GRAVITY_MODIFIER = 0.3f;
+// Exponential damping rate for horizontal and upward motion in water.
+const float WATER_DRAG = 4.0f;
+
+} // namespace
+
 void
 HeavyCoin::update(float dt_sec)
 {
+  const bool in_water = !Sector::get().is_free_of_tiles(get_bbox(), true, Tile::WATER);
+
+  if (in_water)
+  {
+    const float damping = std::exp(-WATER_DRAG * dt_sec);
+    m_physic.set_velocity_x(m_physic.get_velocity_x() * damping);
+    if (m_physic.get_velocity_y() < 0.0f)
+      m_physic.set_velocity_y(m_physic.get_velocity_y() * damping);
+    m_physic.set_gravity_modifier(WATER_GRAVITY_MODIFIER);
+  }
+  else
+  {
+    m_physic.set_gravity_modifier(1.0f);
+  }
+
   // Enable physics.
-  m_col.set_movement(m_physic.get_movement(dt_sec));
+  Vector movement = m_physic.get_movement(dt_sec);
+
+  if (in_water && m_physic.get_velocity_y() > WATER_SINK_SPEED)
+  {
+    // However fast the coin hit the water, it only drifts down slowly.
+    m_physic.set_velocity_y(WATER_SINK_SPEED);
+    movement.y = WATER_SINK_SPEED * dt_sec;
+  }
+
+  m_col.set_movement(movement);
 }

